from taf.gnb.oam.coam.cu.utilities.http_client import HttpClient


class CPCONFIGLicensedv1HttpClient(HttpClient):
    """ This class provides a client for the CP-CONFIG v1 API. """

    def __init__(self, base_url, connection_alias):
        super(CPCONFIGLicensedv1HttpClient, self).__init__(connection_alias)
        self.base_url = base_url + "/api/licensed/v1"

    def reset_cu(self, timeout=30):
        endpoint = '/cu/operations/resets'
        headers = {
            "Content-Type": "application/json",
        }

        return self._send_post_request(endpoint=endpoint, timeout=timeout, headers=headers)

    def trigger_cell_reset(self, dist_name, timeout=30):
        endpoint = '/cells/operations/resets'
        headers = {
            'Content-Type': 'application/json',
            'accept': 'application/json',
        }
        json_data = {
            'distName': dist_name
        }

        return self._send_post_request(endpoint=endpoint, timeout=timeout, json=json_data, headers=headers)

    def get_cell_reset_operation_status(self, operation_id, timeout=30):
        endpoint = f'/cells/operations/resets/{operation_id}'
        headers = {
            'accept': 'application/json',
        }

        return self._send_get_request(endpoint=endpoint, timeout=timeout, headers=headers)

    def delete_cell_reset_operation(self, operation_id, timeout=30):
        endpoint = f'/cells/operations/resets/{operation_id}'
        headers = {
            'accept': 'application/json',
        }

        return self._send_delete_request(endpoint=endpoint, timeout=timeout, headers=headers)
